import cors from 'cors'
import { config } from 'wasp/server'

/**
 * Global server middleware configuration.
 *
 * This function customizes the default Express middleware stack that Wasp
 * installs on every operation and API route.
 */
export const serverMiddlewareFn = (middlewareConfig: Map<string, any>) => {
  // Extend the allowed CORS origins so requests from the local origin
  // http://localhost:5000 are accepted, while keeping the existing/default
  // allowed origins (including the local client at http://localhost:3000).
  middlewareConfig.set(
    'cors',
    cors({ origin: [...config.allowedCORSOrigins, 'http://localhost:5000'] })
  )

  // Add a custom middleware entry that sets the X-Global: enabled response
  // header on every response.
  middlewareConfig.set('globalHeader', (_req: any, res: any, next: any) => {
    res.setHeader('X-Global', 'enabled')
    next()
  })

  return middlewareConfig
}

import express from 'express'

/**
 * GET /api/status
 *
 * Responds with status 200 and JSON body { "status": "ok" }.
 */
export const getStatus = (_req: any, res: any, _context: any) => {
  res.status(200).json({ status: 'ok' })
}

/**
 * POST /api/echo
 *
 * Its route middleware parses the body as raw bytes (express.raw), so
 * `req.body` is a Buffer. Responds with status 200 and JSON body
 * { "bytes": <number> } where <number> is the exact byte length of the
 * raw request body.
 */
export const echo = (req: any, res: any, _context: any) => {
  const body: any = req.body
  const bytes = Buffer.isBuffer(body) ? body.length : 0
  res.status(200).json({ bytes })
}

/**
 * Per-path (namespace) middleware applied to everything under /api.
 *
 * Sets the response header X-Api-Namespace: v1 on every /api/* response.
 */
export const apiNamespaceMiddlewareFn = (middlewareConfig: Map<string, any>) => {
  middlewareConfig.set('apiNamespaceHeader', (_req: any, res: any, next: any) => {
    res.setHeader('X-Api-Namespace', 'v1')
    next()
  })
  return middlewareConfig
}

/**
 * Per-api middleware for the POST /api/echo route only.
 *
 * Replaces the default JSON body parser with a raw body parser (so the
 * handler receives the unparsed request body as raw bytes) and sets the
 * response header X-Echo: raw on that route only.
 */
export const echoMiddlewareFn = (middlewareConfig: Map<string, any>) => {
  // Replace the default JSON body parser with a raw body parser.
  middlewareConfig.delete('express.json')
  middlewareConfig.set('express.raw', express.raw({ type: '*/*' }))

  // Set the X-Echo: raw header on this route only.
  middlewareConfig.set('echoHeader', (_req: any, res: any, next: any) => {
    res.setHeader('X-Echo', 'raw')
    next()
  })

  return middlewareConfig
}

